341	func TestCRDTConcurrentCountersConverge(t *testing.T) {
342		s, _ := Open("")
343		defer func() { _ = s.Close() }()
344		devices := make([]string, 8)
345		for i := range devices {
346			devices[i] = fmt.Sprintf("dev-%d", i)
347		}
348		registerDevices(t, s, devices...)
349	
350		// Every device submits the same cumulative maximum from many goroutines;
351		// the merge is commutative and associative, so the total is deterministic.
352		const rounds = 25
353		var wg sync.WaitGroup
354		start := make(chan struct{})
355		for _, d := range devices {
356			for r := 0; r < rounds; r++ {
357				wg.Add(1)
358				go func(device string, r int) {
359					defer wg.Done()
360					<-start
361					_, _ = s.SubmitCRDTOps("doc", CRDTTypeCounter, []CRDTOp{
362						{ID: fmt.Sprintf("%s-%d", device, r), DeviceID: device, Value: rawInt(int64(r + 1))},
363					})
364				}(d, r)
365			}
366		}
367		close(start)
368		wg.Wait()
369	
370		state, err := s.GetCRDTState("doc")
371		if err != nil {
372			t.Fatal(err)
373		}
374		// No regression can ever be accepted, so each device's max is rounds.
375		if string(state.Value) != fmt.Sprintf("%d", len(devices)*rounds) {
376			t.Fatalf("merged = %s, want %d", state.Value, len(devices)*rounds)
377		}
378	}
