		{http.MethodGet, "/v1/documents/doc/crdt/state/"},
		{http.MethodPost, "/v1/documents/doc/crdt/ops/extra"},
		{http.MethodGet, "/v1/documents/doc/crdt/state/extra"},
		{http.MethodPost, "/v1/documents/doc/crdt"},
