		{http.MethodGet, "/v1/documents/doc/crdt/ops"},
		{http.MethodPost, "/v1/documents/doc/crdt/state"},
		{http.MethodDelete, "/v1/documents/doc/crdt/ops"},
	}
	for _, tc := range bad {
