	if err != nil {
		t.Fatal(err)
	}
	if state.Type != CRDTTypeORSet {
		t.Fatalf("type = %q, want orset", state.Type)
	}
	var elements []string
	if err := json.Unmarshal(state.Value, &elements); err != nil {
		t.Fatalf("value %s is not a string array: %v", state.Value, err)
