func TestCRDTORSetMergeIsOrderIndependent(t *testing.T) {
	s, _ := Open("")
	defer func() { _ = s.Close() }()
	registerDevices(t, s, "dev-1", "dev-2")

	// The same accepted operations in two different arrival orders converge
	// to the same set: the merge is commutative, associative and idempotent.
	// A remove only ever tombstones the adds accepted before it, so both
	// orders keep the element added after (or unknown to) the remove.
	submitORSet(t, s, "doc-a",
		orsetOp("a1", "dev-1", CRDTORSetAdd, "x"),
		orsetOp("r1", "dev-2", CRDTORSetRemove, "x"),
		orsetOp("a2", "dev-2", CRDTORSetAdd, "x"),
		orsetOp("a3", "dev-1", CRDTORSetAdd, "z"),
	)
	submitORSet(t, s, "doc-b",
		orsetOp("a3", "dev-1", CRDTORSetAdd, "z"),
		orsetOp("a2", "dev-2", CRDTORSetAdd, "x"),
		orsetOp("a1", "dev-1", CRDTORSetAdd, "x"),
		orsetOp("r1", "dev-2", CRDTORSetRemove, "x"),
	)
	equalElements(t, orsetState(t, s, "doc-a"), "x", "z")
	equalElements(t, orsetState(t, s, "doc-b"), "x", "z")
}

