246	func TestCRDTSubscribeSilentUntilFirstState(t *testing.T) {
247		srv, _ := newWSTestServer(t)
248		setupSession(t, srv, "dev-1", "sess", "doc", 2)
249	
250		if code, _ := httpGet(t, srv, "/v1/documents/doc/crdt/state"); code != http.StatusNotFound {
251			t.Fatalf("state before ops = %d, want 404", code)
252		}
253	
254		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
255		if conn == nil {
256			t.Fatalf("status = %d, want 101", hs.StatusCode)
257		}
258		defer conn.close()
259	
260		conn.setReadDeadline(300 * time.Millisecond)
261		if _, _, _, ok := conn.readFrameMaybe(); ok {
262			t.Fatal("a frame arrived before the first crdt state")
263		}
264		conn.clearReadDeadline()
265	
266		if code := postCRDTOps(t, srv, "doc", crdtGSetBody("dev-1", crdtGSetOp("g1", "apple"))); code != http.StatusOK {
267			t.Fatalf("submit = %d", code)
268		}
269		state := conn.readCRDTState()
270		if state.Type != "gset" {
271			t.Fatalf("type = %q, want gset", state.Type)
272		}
273		if got := crdtSetElements(t, state); len(got) != 1 || got[0] != "apple" {
274			t.Fatalf("elements = %v, want [apple]", got)
275		}
276	}
277	
278	// Counter commits that advance the per-device maximum push immediately in
279	// commit order; idempotent repeats, equal-value new ops and rejected
280	// regressions change no state and push nothing.
281	func TestCRDTSubscribeCounterPushesOnlyRealChanges(t *testing.T) {
282		srv, _ := newWSTestServer(t)
283		setupSession(t, srv, "dev-1", "sess", "doc", 0)
284	
285		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
286		if conn == nil {
287			t.Fatalf("status = %d", hs.StatusCode)
288		}
289		defer conn.close()
290	
291		// First ever state: 5.
292		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 5))); code != http.StatusOK {
293			t.Fatalf("submit = %d", code)
294		}
295		if n := crdtCounterValue(t, conn.readCRDTState()); n != 5 {
296			t.Fatalf("frame = %d, want 5", n)
297		}
298	
